import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    g = []
    p = 2
    for _ in range(r):
        g.append([int(x) for x in data[p:p + c]])
        p += c
    sr, sc, k = int(data[p]), int(data[p + 1]), int(data[p + 2])
    NEG = -1
    cur = [[NEG] * c for _ in range(r)]
    cur[sr][sc] = g[sr][sc]
    best = cur[sr][sc]
    for _ in range(k):
        nxt = [[NEG] * c for _ in range(r)]
        for i in range(r):
            row = cur[i]
            for j in range(c):
                v = row[j]
                if v < 0:
                    continue
                for ni, nj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                    if 0 <= ni < r and 0 <= nj < c:
                        w = v + g[ni][nj]
                        if w > nxt[ni][nj]:
                            nxt[ni][nj] = w
        cur = nxt
        for row in cur:
            m = max(row)
            if m > best:
                best = m
    print(best)

